import SIZES from '../../public/img/sizes.json';

// Responsive WebP image generated by scripts/make-media.mjs (800w + 1600w; 3:2 except project renders, native ratio).
export default function Img({ name, alt, sizes = '(max-width: 760px) 100vw, 50vw', priority = false, className }) {
  const { w, h } = SIZES[name] || { w: 1600, h: 1067 };
  return (
    <img
      className={className}
      src={`/img/${name}-1600.webp`}
      srcSet={`/img/${name}-800.webp 800w, /img/${name}-1600.webp ${w}w`}
      sizes={sizes}
      width={w}
      height={h}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : undefined}
      decoding="async"
    />
  );
}
